// Successive shortest paths (dense) for the square assignment problem.
// Duals maintained so reduced costs stay nonnegative.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>

extern "C" int solve_lap(int n, const double* cost, int* col_of_row) {
    const double INF = 1e300;
    std::vector<double> u(n, 0.0), v(n, 0.0);     // duals
    std::vector<int> row_of_col(n, -1);
    std::vector<int> parent_col(n);               // predecessor column in alternating path (for columns)
    std::vector<double> dist(n);
    std::vector<char> seen(n);
    std::vector<int> col_of_row_local(n, -1);

    for (int src = 0; src < n; ++src) {
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        std::fill(parent_col.begin(), parent_col.end(), -1);

        // initialize distances from src row
        const double* srow = cost + (int64_t)src * n;
        for (int j = 0; j < n; ++j) {
            dist[j] = srow[j] - u[src] - v[j];
        }

        int sink = -1;
        while (true) {
            // find closest unscanned column
            int jbest = -1;
            double best = INF;
            for (int j = 0; j < n; ++j) if (!seen[j] && dist[j] < best) {
                best = dist[j];
                jbest = j;
            }
            if (jbest < 0) return -1;
            seen[jbest] = 1;

            if (row_of_col[jbest] < 0) {
                sink = jbest;
                // update duals
                // For every scanned column j, v[j] += dist[j] - best
                // For every row whose matched column is scanned, u decreases accordingly
                for (int j = 0; j < n; ++j) if (seen[j]) {
                    double delta = dist[j] - best;
                    v[j] += delta;
                    int i = row_of_col[j];
                    if (i >= 0) u[i] -= delta;
                }
                u[src] += best; // src was not yet matched; its dual absorbs best? 
                // Careful: reduced cost of edges from src:
                // We initialized dist[j] = c(src,j) - u[src] - v[j].
                // After updates, for scanned j, v increased by dist[j]-best, so
                // new reduced = c - u_new - v_new.
                // We want reduced cost of the chosen edge to be 0 and dual feasibility.
                // Standard: u[src] = u[src] + best  (since dist already subtracted old u)
                // Let's verify later by feasibility check.
                break;
            }

            // relax through the matched row of jbest
            int i = row_of_col[jbest];
            const double* row = cost + (int64_t)i * n;
            double base = best; // dist[jbest]
            // reduced cost of (i, j) minus reduced cost of (i, jbest) + dist[jbest]
            // reduced(i,j) = row[j] - u[i] - v[j]
            // reduced(i,jbest) = row[jbest] - u[i] - v[jbest]
            // cand = dist[jbest] + reduced(i,j) - reduced(i,jbest)
            double rijbest = row[jbest] - u[i] - v[jbest];
            for (int j = 0; j < n; ++j) if (!seen[j]) {
                double cand = base + (row[j] - u[i] - v[j]) - rijbest;
                if (cand < dist[j]) {
                    dist[j] = cand;
                    parent_col[j] = jbest;
                }
            }
        }

        // augment along path
        int j = sink;
        while (j >= 0) {
            int jprev = parent_col[j];
            int i;
            if (jprev < 0) {
                i = src;
            } else {
                i = row_of_col[jprev];
            }
            row_of_col[j] = i;
            col_of_row_local[i] = j;
            j = jprev;
        }
    }

    for (int i = 0; i < n; ++i) col_of_row[i] = col_of_row_local[i];
    return 0;
}
}
