// Adapted from the classic Pascal/C implementation (public domain, Jonker & Volgenant 1987).
// Integer-scaled costs for speed and stability; scaling chosen so relative order of
// Euclidean distances (range ~[0, sqrt(2)]) is preserved well beyond 1e-9.
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <algorithm>
#include <cmath>

static constexpr int64_t SCALE = 1000000000LL; // 1e9

extern "C" int solve_lap(int n, const double* cost, int* col_of_row) {
    // Allocate working arrays
    const int64_t BIG = (int64_t)4e18;

    int* x = col_of_row;                 // row -> col
    int* y = (int*)malloc(sizeof(int) * n);          // col -> row
    int* free_rows = (int*)malloc(sizeof(int) * n);
    int* pred = (int*)malloc(sizeof(int) * n);
    int* col = (int*)malloc(sizeof(int) * n);        // scanned list
    int64_t* u = (int64_t*)malloc(sizeof(int64_t) * n);
    int64_t* v = (int64_t*)malloc(sizeof(int64_t) * n);
    int64_t* d = (int64_t*)malloc(sizeof(int64_t) * n);
