/*
 * Jonker-Volgenant algorithm for the linear assignment problem.
 * Adapted from the C++ implementation by Roy Jonker (public domain / widely
 * redistributed), originally:
 *   R. Jonker and A. Volgenant, "A shortest augmenting path algorithm for
 *   dense and sparse linear assignment problems", Computing 38, 325-340, 1987.
 *
 * This version takes a dense double cost matrix and returns the column
 * assigned to each row (minimizing total cost).
 */
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <algorithm>

extern "C" int solve_lap(int n, const double* cost, int* rowsol) {
    // Scale doubles to int64. Distances are in [0, ~1.5]; 1e12 keeps
    // ordering stable far past the 1e-7 validation tolerance.
    const double SCALE = 1e12;
    const int64_t INF = (int64_t)4e18;

    int64_t* c = (int64_t*)malloc(sizeof(int64_t) * (size_t)n * (size_t)n);
    int* colsol = (int*)malloc(sizeof(int) * n);
    int* free_row = (int*)malloc(sizeof(int) * n);
    int* pred = (int*)malloc(sizeof(int) * n);
    int* collist = (int*)malloc(sizeof(int) * n);
    int* matches = (int*)malloc(sizeof(int) * n);
    int64_t* d = (int64_t*)malloc(sizeof(int64_t) * n);
    int64_t* v = (int64_t*)malloc(sizeof(int64_t) * n);
    if (!c || !colsol || !free_row || !pred || !collist || !matches || !d || !v) return -2;

    for (size_t k = 0, N = (size_t)n * n; k < N; ++k) {
        double x = cost[k] * SCALE;
        c[k] = (int64_t)std::llrint(x);
    }

    // ---------- column reduction ----------
    for (int j = 0; j < n; ++j) colsol[j] = -1;
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    // v[j] = min_i c[i,j]
    for (int j = 0; j < n; ++j) {
        int64_t h = c[j];
        int i_min = 0;
        for (int i = 1; i < n; ++i) {
            int64_t cc = c[(size_t)i * n + j];
            if (cc < h) { h = cc; i_min = i; }
        }
        v[j] = h;
        // assign if row free (scan columns in reverse so later columns win ties? 
        // we'll do a second pass)
        (void)i_min;
    }

    // assign each column to a row achieving the minimum, greedily, reverse order
    for (int j = n - 1; j >= 0; --j) {
        int64_t h = v[j];
        for (int i = 0; i < n; ++i) {
            if (rowsol[i] < 0 && c[(size_t)i * n + j] == h) {
                rowsol[i] = j;
                colsol[j] = i;
                break;
            }
        }
    }

    // ---------- reduction transfer ----------
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) {
            free_row[numfree++] = i;
        } else {
            int j1 = rowsol[i];
            int64_t min1 = INF;
            const int64_t* row = c + (size_t)i * n;
            for (int j = 0; j < n; ++j) if (j != j1) {
                int64_t red = row[j] - v[j];
                if (red < min1) min1 = red;
            }
            // transfer reduction to column dual of the matched column
            v[j1] -= min1;
        }
    }

    // ---------- augmenting row reduction ----------
    int loopcnt = 0;
    while (loopcnt < 2) {
        loopcnt++;
        int k = 0;
        int prev_numfree = numfree;
        numfree = 0;
        while (k < prev_numfree) {
            int i = free_row[k++];
            const int64_t* row = c + (size_t)i * n;
            int64_t umin = row[0] - v[0];
            int j1 = 0;
            int64_t usub = INF;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
                int64_t h = row[j] - v[j];
                if (h < umin) {
                    usub = umin;
                    j2 = j1;
                    umin = h;
                    j1 = j;
                } else if (h < usub) {
                    usub = h;
                    j2 = j;
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) {
                v[j1] -= (usub - umin);
            } else if (i0 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            if (i0 >= 0) {
                if (umin < usub) {
                    free_row[--k] = i0;
                } else {
                    free_row[numfree++] = i0;
                }
                rowsol[i0] = -1;
            }
            rowsol[i] = j1;
            colsol[j1] = i;
        }
    }

    // ---------- augmentation ----------
    int f = 0;
    // recompute free rows
    numfree = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) free_row[numfree++] = i;

    for (int freerow_idx = 0; freerow_idx < numfree; ++freerow_idx) {
        int freerow = free_row[freerow_idx];
        const int64_t* frow = c + (size_t)freerow * n;

        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0;
        int last = 0;          // last column in ready list? we'll use low/up scan
        int endofpath = -1;
        int64_t minv = INF;
        int minj = 0;

        // find initial minimum
        for (int j = 0; j < n; ++j) {
            if (d[j] < minv) { minv = d[j]; minj = j; }
        }
        // Dijkstra
        int unass = -1;
        // Use a "ready" threshold scheme from JV:
        // We scan columns; those with dist == min are "ready".
        // Simpler correct version: naive Dijkstra scan (still with the JV initialization benefit).
        std::memset(matches, 0, sizeof(int) * n); // seen
        while (true) {
            int jbest = -1;
            int64_t best = INF;
            for (int j = 0; j < n; ++j) if (!matches[j] && d[j] < best) {
                best = d[j];
                jbest = j;
            }
            matches[jbest] = 1;
            minv = best;
            if (colsol[jbest] < 0) { unass = jbest; break; }
            int i = colsol[jbest];
            const int64_t* row = c + (size_t)i * n;
            int64_t base_red = row[jbest] - v[jbest];
            for (int j = 0; j < n; ++j) if (!matches[j]) {
                int64_t cand = best + (row[j] - v[j]) - base_red;
                if (cand < d[j]) {
                    d[j] = cand;
                    pred[j] = i;
                }
            }
        }

        // update column duals
        for (int j = 0; j < n; ++j) if (matches[j]) {
            v[j] += d[j] - minv;
        }

        // augment
        int j = unass;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            j = jnext;
            if (i == freerow) break;
        }
        (void)low; (void)up; (void)last; (void)endofpath; (void)minj; (void)f;
    }

    free(c); free(colsol); free(free_row); free(pred); free(collist); free(matches); free(d); free(v);
    return 0;
}
