 * Faithful port of the classic implementation (Roy Jonker, MagicLogic /
 * public-domain redistribution used by scipy and py-lapsolver).
 *
 * Cost is scaled from double by a caller-provided factor via llrint.
 */
#include <cstdint>
#include <cstdlib>
#include <cstring>
