/*
 * LAPJV dense assignment (min cost), integer costs.
 * Column reduction + reduction transfer + augmenting row reduction +
 * shortest augmenting path with the Jonker-Volgenant "todo/ready" scan.
 *
 * Ported from the classic public-domain implementation (Jonker & Volgenant 1987,
 * C port by Roy Jonker / widely used lapjv).
 */
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <cstdio>
#include <chrono>

extern "C" int solve_lap(int dim, const double* cost_in, int* rowsol) {
