        }
    }

    // ---------- AUGMENTATION with JV todo/ready scan ----------
    for (int f = 0; f < numfree; ++f) {
        int freerow = freer[f];
        const int64_t* frow = cost + (size_t)freerow * n;

        for (int j = 0; j < n; ++j) {
