        // Actually in JV:
        //   low = number of columns in the shortest path tree (finalized)
        //   up  = number of columns that are "ready" (have current min dist, not yet expanded) + low?
        // I'll use a clearer variant that still skips columns worse than the current minimum:
        // Maintain unexplored set as collist[k .. n). Each phase, find min dist among unexplored,
        // then expand ALL unexplored columns that equal that min (they become finalized),
        // relaxing through matched rows.

        int unexplored_start = 0; // collist[unexplored_start .. n) not finalized
        while (endofpath < 0) {
            // find minimum dist among not finalized
            int64_t mind = BIG;
            for (int t = unexplored_start; t < n; ++t) {
                int j = collist[t];
                if (d[j] < mind) mind = d[j];
            }
            minv = mind;
            // partition: move columns with d==mind to the front of unexplored, expand them
            int write = unexplored_start;
            int new_start = unexplored_start;
            // first count / swap equals to front
            for (int t = unexplored_start; t < n; ++t) {
                int j = collist[t];
                if (d[j] == mind) {
                    collist[t] = collist[write];
                    collist[write] = j;
                    write++;
                }
            }
            int expand_end = write; // [unexplored_start, expand_end) are finalized this round
            // check for free column
            for (int t = unexplored_start; t < expand_end; ++t) {
                int j = collist[t];
                if (colsol[j] < 0) { endofpath = j; break; }
            }
            if (endofpath >= 0) {
                unexplored_start = expand_end;
                break;
            }
            // relax through matched rows of expanded columns
            for (int t = unexplored_start; t < expand_end; ++t) {
                int j1 = collist[t];
                int i = colsol[j1];
                const int64_t* row = cost + (size_t)i * n;
                int64_t base = row[j1] - v[j1];
                int64_t h = mind - base; // so cand = row[j]-v[j] + h
                for (int t2 = expand_end; t2 < n; ++t2) {
                    int j = collist[t2];
                    int64_t cand = row[j] - v[j] + h;
                    if (cand < d[j]) {
                        d[j] = cand;
                        pred[j] = i;
                    }
                }
            }
            unexplored_start = expand_end;
            if (unexplored_start >= n) return -1;
        }

        // update duals: finalized columns are collist[0 .. unexplored_start)
        // plus endofpath which is among them
        for (int t = 0; t < unexplored_start; ++t) {
            int j = collist[t];
            v[j] += d[j] - minv;
        }

        // augment
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int next = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = next;
        }
        (void)up; (void)low; (void)last;
    }

    std::free(cost); std::free(colsol); std::free(freer); std::free(pred);
    std::free(collist); std::free(matches); std::free(d); std::free(v);
    return 0;
}
