    int* pred = (int*)malloc(sizeof(int) * n);
    int* collist = (int*)malloc(sizeof(int) * n);
    int64_t* d = (int64_t*)malloc(sizeof(int64_t) * n);
    int64_t* v = (int64_t*)malloc(sizeof(int64_t) * n);
    if (!cost || !colsol || !freer || !pred || !collist || !d || !v) return -2;

    for (size_t k = 0, N = (size_t)n * n; k < N; ++k)
        cost[k] = (int64_t)std::llrint(cost_in[k] * SCALE);

    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    // COLUMN REDUCTION (reverse column order, classic)
    for (int j = n - 1; j >= 0; --j) {
        const int64_t* colp = cost + j; // not contiguous; scan rows
        int64_t minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            int64_t c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
        }
        (void)colp;
    }

    // REDUCTION TRANSFER
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) {
            freer[numfree++] = i;
        } else {
            int j1 = rowsol[i];
            int64_t minv = BIG;
            const int64_t* row = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) {
                if (j == j1) continue;
