                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0) { j1 = j2; i0 = colsol[j1]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) freer[numfree++] = i0;
        }
    }

    // AUGMENTATION: classic JV todo/ready
    // low = # columns with finalized dual (in shortest path tree)
    // up  = # columns scanned at current price (ready to expand) 
    // last = end of columns still eligible (d < h)
    // unlabelled columns with d >= h are kept after `last` and skipped.
    for (int f = 0; f < numfree; ++f) {
        int freerow = freer[f];
        const int64_t* frow = cost + (size_t)freerow * n;

        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
