        int low = 0, up = 0, last = n - 1;
        int endofpath = -1;
        int64_t minv = d[0];
        int minj = 0;
        for (int j = 1; j < n; ++j) if (d[j] < minv) { minv = d[j]; minj = j; }

        // swap min column to position 0
        collist[0] = minj;
        collist[minj] = 0;

        while (endofpath < 0) {
