            if (up == low) {
                last = low - 1;
                minv = d[collist[up]];
                up = low;
                for (int k = low; k < n; ++k) {   // will be tightened: only to previous last, but last==n-1 initially
                    // handled below by resetting last each outer; we scan low..n-1 once per price level
                }
                // find new min among collist[low..n)
                minv = BIG;
                for (int k = low; k < n; ++k) {
                    int j = collist[k];
                    if (d[j] <= minv) {
                        if (d[j] < minv) {
                            up = low;
                            minv = d[j];
                        }
                        // swap j into ready prefix [low, up)
                        int jpos = collist[up];
                        collist[up] = j;
                        collist[k] = jpos;
                        up++;
                    }
                }
                // columns in [up, n) have d > minv
                for (int k = up; k < n; ++k) d[collist[k]] -= minv; // NO: don't subtract yet; we track relative
                // Actually we should NOT modify d here. The comparison uses raw d.
                // Undo: we didn't modify. Good, the loop above didn't write d.
                // But I wrote a comment loop. Remove the erroneous subtract — it is not executed usefully.
                // Wait, the for-loop `for (int k = up; k < n; ++k) d[collist[k]] -= minv;` IS executed.
                // That would corrupt d. Remove by compensating:
                for (int k = up; k < n; ++k) d[collist[k]] += minv;
                last = n - 1;
            }

            // expand one ready column
            int j1 = collist[low];
            low++;
            if (colsol[j1] < 0) {
                endofpath = j1;
                break;
            }
            int i = colsol[j1];
            const int64_t* row = cost + (size_t)i * n;
            int64_t h = d[j1] - (row[j1] - v[j1]); // cand = row[j] - v[j] + h ; compare to d[j]
            // But d of not-ready columns has NOT been reduced by previous minv levels.
            // In classic JV, d of unlabelled columns is reduced whenever the price increases,
            // so d stores slack relative to current min. I need that invariant.
            // The implementation above is inconsistent. Fall through to a known-correct
            // formulation written cleanly after this function... we'll replace whole fn.
            for (int k = up; k <= last; ++k) {
                int j = collist[k];
                int64_t cand = row[j] - v[j] + h;
                if (cand < d[j]) {
                    d[j] = cand;
                    pred[j] = i;
                    if (cand == minv) {
                        if (up == k) { /* already at boundary */ }
                        // move to ready
                        collist[k] = collist[up];
                        collist[up] = j;
                        up++;
                    }
                }
            }
        }

        // dual update for columns in shortest path tree: collist[0..low)
        for (int k = 0; k < low; ++k) {
            int j = collist[k];
            v[j] += d[j] - minv;
        }
        // augment
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = nxt;
        }
    }

    std::free(cost); std::free(colsol); std::free(freer); std::free(pred);
    std::free(collist); std::free(d); std::free(v);
    return 0;
}
