/*
 * Jonker-Volgenant dense LAP, integer costs.
 * Control flow follows the classic lapjv (public domain, Roy Jonker).
 * Costs are scaled from double via llrint.
 *
 * rowsol[i] = column assigned to row i.
 */
#include <cstdint>
#include <cstdlib>
#include <cmath>

extern "C" int solve_lap(int dim, const double* assigncost_in, int* rowsol) {
    const double SCALE = 1e9;
    const int64_t BIG = (int64_t)3e18;
    const int n = dim;

    int64_t* assigncost = (int64_t*)malloc(sizeof(int64_t) * (size_t)n * n);
    int* colsol = (int*)malloc(sizeof(int) * n);
    int* freer = (int*)malloc(sizeof(int) * n);
    int* pred = (int*)malloc(sizeof(int) * n);
    int* collist = (int*)malloc(sizeof(int) * n);
    int64_t* d = (int64_t*)malloc(sizeof(int64_t) * n);
    int64_t* v = (int64_t*)malloc(sizeof(int64_t) * n);
    if (!assigncost || !colsol || !freer || !pred || !collist || !d || !v) return -2;

    for (size_t k = 0, N = (size_t)n * n; k < N; ++k)
        assigncost[k] = (int64_t)std::llrint(assigncost_in[k] * SCALE);

    // COLUMN REDUCTION
    for (int i = 0; i < n; ++i) rowsol[i] = -1;
    for (int j = n - 1; j >= 0; --j) {
        int64_t minv = assigncost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            int64_t c = assigncost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
        }
    }

    // REDUCTION TRANSFER
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] == -1)
            freer[numfree++] = i;
        else {
            int j1 = rowsol[i];
            int64_t minv = BIG;
            const int64_t* row = assigncost + (size_t)i * n;
            for (int j = 0; j < n; ++j) if (j != j1) {
                int64_t red = row[j] - v[j];
                if (red < minv) minv = red;
            }
            v[j1] -= minv;
        }
    }

    // AUGMENTING ROW REDUCTION
    int loopcnt = 0;
    do {
        loopcnt++;
        int k = 0;
        int prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            int i = freer[k];
            k++;
            int64_t umin = BIG, usubmin = BIG;
            int j1 = 0, j2 = 0;
            const int64_t* row = assigncost + (size_t)i * n;
            for (int j = 0; j < n; ++j) {
                int64_t h = row[j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                        j2 = j;
                    } else {
                        usubmin = umin;
                        umin = h;
                        j2 = j1;
                        j1 = j;
                    }
                }
            }
            int i0 = colsol[j1];
            int vj1new = 0; // unused, keep dual update explicit
            (void)vj1new;
            if (umin < usubmin)
                v[j1] -= (usubmin - umin);
            else if (i0 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usubmin)
                    freer[--k] = i0;       // immediate reprocess
                else
                    freer[numfree++] = i0;
            }
        }
    } while (loopcnt < 2);

    // AUGMENTATION
    for (int f = 0; f < numfree; ++f) {
        int freerow = freer[f];
        const int64_t* frow = assigncost + (size_t)freerow * n;

        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0;
        int unassignedfound = 0;
        int last = 0;
        int endofpath = -1;
        int64_t min = BIG;

        // find initial min and put it first
        {
            int j = 0;
            min = d[0];
            for (int jj = 1; jj < n; ++jj) if (d[jj] < min) { min = d[jj]; j = jj; }
            collist[0] = j;
            collist[j] = 0;
        }

        do {
            if (up == low) {
                last = low - 1;
                min = d[collist[up]];
                up = low;
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    int64_t h = d[j];
                    if (h <= min) {
                        if (h < min) {
                            up = low;
                            min = h;
                        }
                        collist[k] = collist[up];
                        collist[up] = j;
                        up++;
                    }
                }
                for (int k = low; k < up; ++k) {
                    if (colsol[collist[k]] < 0) {
                        endofpath = collist[k];
                        unassignedfound = 1;
                        break;
                    }
                }
            }
            if (!unassignedfound) {
                int j1 = collist[low];
                low++;
                int i = colsol[j1];
                const int64_t* row = assigncost + (size_t)i * n;
                int64_t h = row[j1] - v[j1] - min;
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    int64_t cred = row[j] - v[j] - h;
                    if (cred < d[j]) {
                        d[j] = cred;
                        pred[j] = i;
                        if (cred == min) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                unassignedfound = 1;
                                // still swap into ready so low..up covers it? not required for augment
                            }
                            collist[k] = collist[up];
                            collist[up++] = j;
                        }
                    }
                }
            }
        } while (!unassignedfound);

        // update column prices
        for (int k = 0; k < low; ++k) {
            int j1 = collist[k];
            v[j1] += d[j1] - min;
        }

        // augmentation
        int i, j = endofpath;
        do {
            i = pred[j];
            colsol[j] = i;
            int j1 = j;
            j = rowsol[i];
            rowsol[i] = j1;
        } while (i != freerow);
        (void)last;
    }

    std::free(assigncost); std::free(colsol); std::free(freer); std::free(pred);
    std::free(collist); std::free(d); std::free(v);
    return 0;
}
