/*
 * Assignment via column reduction + one deferred row-reduction pass +
 * successive shortest paths (Dijkstra with a binary heap).
 * Integer costs (scaled doubles). Returns column index per row.
 */
#include <cstdint>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include <vector>
#include <queue>
#include <utility>

extern "C" int solve_lap(int dim, const double* cost_in, int* rowsol) {
    const double SCALE = 1e9;
    const int64_t BIG = (int64_t)3e18;
    const int n = dim;

    int64_t* cost = (int64_t*)malloc(sizeof(int64_t) * (size_t)n * n);
    int* colsol = (int*)malloc(sizeof(int) * n);
    int* freer = (int*)malloc(sizeof(int) * n);
    int* pred = (int*)malloc(sizeof(int) * n);
    int64_t* d = (int64_t*)malloc(sizeof(int64_t) * n);
    int64_t* v = (int64_t*)malloc(sizeof(int64_t) * n);
    char* seen = (char*)malloc(n);
    if (!cost || !colsol || !freer || !pred || !d || !v || !seen) return -2;

    for (size_t k = 0, N = (size_t)n * n; k < N; ++k)
        cost[k] = (int64_t)std::llrint(cost_in[k] * SCALE);

    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    // column reduction
    for (int j = n - 1; j >= 0; --j) {
        int64_t minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            int64_t c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) { rowsol[imin] = j; colsol[j] = imin; }
        else colsol[j] = -1;
    }

    // reduction transfer
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) freer[numfree++] = i;
        else {
            int j1 = rowsol[i];
            int64_t minv = BIG;
            const int64_t* row = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) if (j != j1) {
                int64_t red = row[j] - v[j];
                if (red < minv) minv = red;
            }
            v[j1] -= minv;
        }
    }

    // one deferred augmenting row reduction
    {
        int k = 0, prv = numfree;
        numfree = 0;
        while (k < prv) {
            int i = freer[k++];
            int64_t umin = BIG, usub = BIG;
            int j1 = 0, j2 = 0;
            const int64_t* row = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) {
                int64_t h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0) { j1 = j2; i0 = colsol[j1]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) freer[numfree++] = i0;
        }
    }

    // heap dijkstra augmentation
    using P = std::pair<int64_t, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

    for (int f = 0; f < numfree; ++f) {
        int freerow = freer[f];
        const int64_t* frow = cost + (size_t)freerow * n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            seen[j] = 0;
        }
        pq = {};
        for (int j = 0; j < n; ++j) pq.emplace(d[j], j);

        int endofpath = -1;
        int64_t minv = 0;
        while (!pq.empty()) {
            auto [dist, jbest] = pq.top();
            pq.pop();
            if (seen[jbest]) continue;
            if (dist != d[jbest]) continue;
            seen[jbest] = 1;
            minv = dist;
            if (colsol[jbest] < 0) { endofpath = jbest; break; }
            int i = colsol[jbest];
            const int64_t* row = cost + (size_t)i * n;
            int64_t h = dist - (row[jbest] - v[jbest]);
            for (int j = 0; j < n; ++j) if (!seen[j]) {
                int64_t cand = row[j] - v[j] + h;
                if (cand < d[j]) {
                    d[j] = cand;
                    pred[j] = i;
                    pq.emplace(cand, j);
                }
            }
        }
        if (endofpath < 0) { 
            std::free(cost); std::free(colsol); std::free(freer); std::free(pred);
            std::free(d); std::free(v); std::free(seen);
            return -1;
        }
        for (int j = 0; j < n; ++j) if (seen[j]) v[j] += d[j] - minv;

        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = nxt;
        }
    }

    std::free(cost); std::free(colsol); std::free(freer); std::free(pred);
    std::free(d); std::free(v); std::free(seen);
    return 0;
}
