    const double SCALE = 1e6; // coarser: distances unique at ~1e-6 median gap is 1e-6, min gap 1e-11. 
    // 1e6 may collapse some orderings! Use 1e9 for correctness, auction still works.
    const int64_t S = 1000000000LL;
