    // approach by scaling benefits * n and using eps = 1.
    // Simpler: scale benefits by n, target eps = 1.
    // Re-scale:
    // We'll just multiply benefits by n now.
    for (size_t k = 0, N = (size_t)n * n; k < N; ++k) a[k] *= n;
    eps *= n;

    int nassigned = 0;
    while (eps >= 1) {
        // reset assignment for this scale? Standard auction scaling keeps prices, resets assignment.
        std::memset(assigned, 0, n);
        for (int j = 0; j < n; ++j) owner[j] = -1;
        nassigned = 0;
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;

        int guard = 0;
        const int GUARD_MAX = n * 50;
        while (nun > 0 && guard < GUARD_MAX) {
            guard++;
            int nun2 = 0;
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                const int64_t* row = a + (size_t)i * n;
                int64_t best = -(int64_t)9e18, second = -(int64_t)9e18;
                int jbest = 0;
                for (int j = 0; j < n; ++j) {
                    int64_t val = row[j] - price[j];
                    if (val > best) { second = best; best = val; jbest = j; }
                    else if (val > second) second = val;
                }
                int64_t bid = price[jbest] + (best - second) + eps;
                // if someone owns jbest, they become unassigned
                int prev = owner[jbest];
                if (prev >= 0) {
                    assigned[prev] = 0;
                    unassigned[nun2++] = prev;
                } else {
                    nassigned++;
                }
                owner[jbest] = i;
                assigned[i] = 1;
                price[jbest] = bid;
            }
            nun = nun2;
        }
        if (nun > 0) {
            // failed to assign at this eps (cycle). Reduce eps anyway and continue; 
            // if final fails, return -1
        }
        if (eps == 1) break;
        eps = std::max<int64_t>(eps / 4, 1);
        (void)GUARD_MAX;
    }

    // build rowsol
    int got = 0;
    for (int i = 0; i < n; ++i) rowsol[i] = -1;
    for (int j = 0; j < n; ++j) if (owner[j] >= 0) { rowsol[owner[j]] = j; got++; }
    int rc = (got == n) ? 0 : -1;

    std::free(a); std::free(price); std::free(owner); std::free(assigned); std::free(unassigned);
    return rc;
}
