/*
 * Parallel auction on K-nearest columns per row.
 * Neighbor selection and bidding scans are threaded.
 * Integer benefits scaled by n so eps=1 is optimal on the candidate graph.
 */
#include <cstdint>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include <algorithm>
#include <thread>
#include <vector>

static int NTHREADS = 4;

struct SelJob {
    const double* cost;
    int n, K;
    int* neigh;
    int64_t* brow;
    int64_t S;
};

static void select_range(const SelJob& job, int i0, int i1) {
    const int n = job.n, K = job.K;
    std::vector<int64_t> tmp(n);
    std::vector<int> order(n);
    for (int i = i0; i < i1; ++i) {
        const double* row = job.cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            tmp[j] = (int64_t)std::llrint(row[j] * (double)job.S);
            order[j] = j;
        }
        std::nth_element(order.begin(), order.begin() + K, order.end(),
                         [&](int a, int b){ return tmp[a] < tmp[b]; });
        for (int t = 0; t < K; ++t) {
            int j = order[t];
            job.neigh[(size_t)i * K + t] = j;
            job.brow[(size_t)i * K + t] = -tmp[j] * n;
        }
    }
}

extern "C" int solve_auction_k(int n, const double* cost_in, int K, int* rowsol) {
    if (K > n) K = n;
    const int64_t S = 1000000000LL;

