    int64_t* price = (int64_t*)calloc(n, sizeof(int64_t));
    int* owner = (int*)malloc(sizeof(int) * n);
    int* unassigned = (int*)malloc(sizeof(int) * n);
    int* unassigned2 = (int*)malloc(sizeof(int) * n);
    char* assigned = (char*)calloc(n, 1);
    if (!neigh || !brow || !price || !owner || !unassigned || !unassigned2 || !assigned) return -2;

    SelJob job{cost_in, n, K, neigh, brow, S};
    {
        int T = std::min(NTHREADS, n);
        std::vector<std::thread> th;
        int chunk = (n + T - 1) / T;
        for (int t = 0; t < T; ++t) {
            int i0 = t * chunk, i1 = std::min(n, i0 + chunk);
            if (i0 >= n) break;
            th.emplace_back(select_range, std::cref(job), i0, i1);
        }
        for (auto& t : th) t.join();
    }

    int64_t eps = S * n / 4;
    if (eps < 1) eps = 1;

    // bidding is sequential because of price/owner conflicts, but each bid scans only K
    while (true) {
        std::memset(assigned, 0, n);
        for (int j = 0; j < n; ++j) owner[j] = -1;
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;

        int guard = 0;
        const int GUARD_MAX = n * 30;
        while (nun > 0 && guard < GUARD_MAX) {
            guard++;
            int nun2 = 0;
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                const int* nb = neigh + (size_t)i * K;
                const int64_t* br = brow + (size_t)i * K;
                int64_t best = -(int64_t)8e18, second = -(int64_t)8e18;
                int jbest = nb[0];
                for (int t2 = 0; t2 < K; ++t2) {
                    int j = nb[t2];
                    int64_t val = br[t2] - price[j];
                    if (val > best) { second = best; best = val; jbest = j; }
                    else if (val > second) second = val;
                }
                int64_t bid = price[jbest] + (best - second) + eps;
                int prev = owner[jbest];
                if (prev >= 0) {
                    unassigned2[nun2++] = prev;
                }
                owner[jbest] = i;
                price[jbest] = bid;
            }
            // swap buffers
            std::swap(unassigned, unassigned2);
            nun = nun2;
        }
        if (eps == 1) {
            int rc = (nun == 0) ? 0 : -1;
            if (rc == 0) {
                for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            }
            std::free(neigh); std::free(brow); std::free(price); std::free(owner);
            std::free(unassigned); std::free(unassigned2); std::free(assigned);
            return rc;
        }
        eps = std::max<int64_t>(eps / 5, 1);
    }
}
