/*
 * Gauss-Seidel auction on K nearest, plus a Jacobi (forward) variant toggle.
 * Also tries a "cost-scaling push" style: bid all currently unassigned in parallel-friendly
 * Jacobi mode where bids are computed from a snapshot of prices, then applied.
 */
#include <cstdint>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include <algorithm>
#include <thread>
#include <vector>
#include <atomic>

static constexpr int NTHREADS = 4;

extern "C" int solve_auction_k(int n, const double* cost_in, int K, int* rowsol) {
    if (K > n) K = n;
    const int64_t S = 1000000000LL;

    int* neigh = (int*)malloc(sizeof(int) * (size_t)n * K);
    int64_t* brow = (int64_t*)malloc(sizeof(int64_t) * (size_t)n * K);
    int64_t* price = (int64_t*)calloc(n, sizeof(int64_t));
    int* owner = (int*)malloc(sizeof(int) * n);
    if (!neigh || !brow || !price || !owner) return -2;

    // parallel neighbor select
    auto select_range = [&](int i0, int i1) {
        std::vector<int64_t> tmp(n);
        std::vector<int> order(n);
        for (int i = i0; i < i1; ++i) {
            const double* row = cost_in + (size_t)i * n;
            for (int j = 0; j < n; ++j) {
                tmp[j] = (int64_t)std::llrint(row[j] * (double)S);
                order[j] = j;
            }
            std::nth_element(order.begin(), order.begin() + K, order.end(),
                             [&](int a, int b){ return tmp[a] < tmp[b]; });
            for (int t = 0; t < K; ++t) {
                int j = order[t];
                neigh[(size_t)i * K + t] = j;
                brow[(size_t)i * K + t] = -tmp[j] * (int64_t)n;
            }
        }
    };
    {
        std::vector<std::thread> th;
        int chunk = (n + NTHREADS - 1) / NTHREADS;
        for (int t = 0; t < NTHREADS; ++t) {
            int i0 = t * chunk, i1 = std::min(n, i0 + chunk);
            if (i0 < n) th.emplace_back(select_range, i0, i1);
        }
        for (auto& t : th) t.join();
    }

    // Jacobi auction with epsilon scaling.
    // Each round: every unassigned person computes a bid from current prices (read-only),
    // then we apply the highest bid per object.
    int64_t eps = S * (int64_t)n / 8;
    if (eps < 1) eps = 1;

    std::vector<int> unassigned(n), next_un(n);
    std::vector<int64_t> bid_price(n);
    std::vector<int> bid_who(n);
    std::vector<char> is_un(n);

    while (true) {
        std::fill(owner, owner + n, -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int guard = 0;
        const int GUARD = n * 20;

        while (nun > 0 && guard < GUARD) {
            guard++;
            std::fill(bid_who.begin(), bid_who.end(), -1);
            // compute bids (could parallelize)
            // store best bid per object in a first-come; conflicts resolved by scanning
            // Use per-thread local bid tables then merge — for K scan the compute is the cost.
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                const int* nb = neigh + (size_t)i * K;
                const int64_t* br = brow + (size_t)i * K;
                int64_t best = -(int64_t)8e18, second = -(int64_t)8e18;
                int jbest = nb[0];
                for (int t2 = 0; t2 < K; ++t2) {
                    int64_t val = br[t2] - price[nb[t2]];
                    if (val > best) { second = best; best = val; jbest = nb[t2]; }
                    else if (val > second) second = val;
                }
                int64_t bprice = price[jbest] + (best - second) + eps;
                // keep highest bid
                if (bid_who[jbest] < 0 || bprice > bid_price[jbest]) {
                    bid_who[jbest] = i;
                    bid_price[jbest] = bprice;
                }
            }
            // apply bids; losers stay unassigned, displaced owners become unassigned
            std::fill(is_un.begin(), is_un.end(), 0);
            for (int j = 0; j < n; ++j) {
                int i = bid_who[j];
                if (i < 0) continue;
                int prev = owner[j];
                if (prev >= 0 && prev != i) is_un[prev] = 1;
                owner[j] = i;
                price[j] = bid_price[j];
            }
            // anyone who bid but didn't win their object is unassigned
            // (they might have won a different object — check owner)
            // Mark winners
            std::vector<char> won(n, 0);
            for (int j = 0; j < n; ++j) if (owner[j] >= 0) won[owner[j]] = 1;
            int nun2 = 0;
            for (int i = 0; i < n; ++i) if (!won[i]) next_un[nun2++] = i;
            nun = nun2;
            unassigned.swap(next_un);
        }

        if (eps == 1) {
            int rc = (nun == 0) ? 0 : -1;
            if (rc == 0) for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            std::free(neigh); std::free(brow); std::free(price); std::free(owner);
            return rc;
        }
        eps = std::max<int64_t>(eps / 4, 1);
    }
}
