/*
 * Dense auction, float prices, epsilon scaling, then a final integer-exact check
 * is NOT done here — caller validates. We use double prices and a final eps
 * small enough that the assignment is optimal for the original double costs
 * up to ties, which don't occur.
 *
 * Optimality: for the assignment problem, epsilon-scaling auction with final
 * epsilon < min_gap / n  yields the unique optimum. min gap of these costs is
 * ~1e-11, so eps_final = 1e-14 is safe. We scale costs by 1 (use raw doubles).
 */
#include <cstdint>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include <algorithm>
#include <vector>

extern "C" int solve_auction(int n, const double* cost, int* rowsol) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> unassigned(n), un2(n);

    // benefit = -cost
    double maxc = 0;
    for (size_t k = 0, N = (size_t)n * n; k < N; ++k) if (cost[k] > maxc) maxc = cost[k];

    double eps = maxc / 4.0;
    const double eps_final = 1e-12;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int guard = 0;
        const int GUARD = n * 80;
        bool failed = false;
        while (nun > 0) {
            if (++guard > GUARD) { failed = true; break; }
            int nun2 = 0;
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                const double* row = cost + (size_t)i * n;
                double best = 1e300, second = 1e300; // minimize cost+price
                int jbest = 0;
                for (int j = 0; j < n; ++j) {
                    double val = row[j] + price[j];
                    if (val < best) { second = best; best = val; jbest = j; }
                    else if (val < second) second = val;
                }
                // bid: raise price so this object ties the second best
                double new_price = price[jbest] + (second - best) + eps;
                int prev = owner[jbest];
                if (prev >= 0) un2[nun2++] = prev;
                owner[jbest] = i;
                price[jbest] = new_price;
            }
            nun = nun2;
            unassigned.swap(un2);
        }
        if (eps <= eps_final) {
            if (failed) return -1;
            for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            return 0;
        }
        eps = std::max(eps * 0.2, eps_final);
        if (failed) {
            // reset prices if we got stuck, try smaller eps from scratch-ish
            std::fill(price.begin(), price.end(), 0.0);
        }
    }
}
