/*
 * Dense epsilon-scaling auction, NEON-vectorized row scans, 4 threads
 * cooperating on each person's scan? Scans are per-row and short (600).
 * Instead, parallelize across unassigned persons using Jacobi auction:
 * each thread computes bids for a subset, then we merge.
 *
 * For speed we use Gauss-Seidel but parallelize the scan of one row with NEON,
 * and also run 4 independent row-bids... conflicts. Jacobi is easier to parallelize.
 *
 * Hybrid: Gauss-Seidel (fast convergence) with NEON scan. 4x from NEON on the
 * inner loop could turn 20ms into ~8ms. Not 20x. 
 *
 * REAL plan for 20x: parallel Jacobi over 4 threads, each handling n/4 persons,
 * plus NEON. Convergence of Jacobi is worse but wall time may drop.
 */
#include <cstdint>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include <algorithm>
#include <thread>
#include <vector>
#include <arm_neon.h>

static inline void best_two(const double* row, const double* price, int n,
                            double& best, double& second, int& jbest) {
    // scalar fallback tail handled inside
    best = 1e300; second = 1e300; jbest = 0;
    int j = 0;
    // process 4 at a time
    float64x2_t b0 = vdupq_n_f64(1e300), b1 = vdupq_n_f64(1e300);
    // can't easily track argmin in NEON portably without scalar compare of the 4.
    // Do blocks of 8, then scalar among candidates? The argmin requires checking all.
    // Vectorized min reduction still needs scalar argmin pass OR we compare lanes.
    for (; j + 4 <= n; j += 4) {
        float64x2_t c0 = vaddq_f64(vld1q_f64(row + j), vld1q_f64(price + j));
        float64x2_t c1 = vaddq_f64(vld1q_f64(row + j + 2), vld1q_f64(price + j + 2));
        double v0 = vgetq_lane_f64(c0, 0);
        double v1 = vgetq_lane_f64(c0, 1);
        double v2 = vgetq_lane_f64(c1, 0);
        double v3 = vgetq_lane_f64(c1, 1);
        // unroll comparisons
        if (v0 < best) { second = best; best = v0; jbest = j; }
        else if (v0 < second) second = v0;
        if (v1 < best) { second = best; best = v1; jbest = j + 1; }
        else if (v1 < second) second = v1;
        if (v2 < best) { second = best; best = v2; jbest = j + 2; }
        else if (v2 < second) second = v2;
        if (v3 < best) { second = best; best = v3; jbest = j + 3; }
        else if (v3 < second) second = v3;
    }
    for (; j < n; ++j) {
        double val = row[j] + price[j];
        if (val < best) { second = best; best = val; jbest = j; }
        else if (val < second) second = val;
    }
    (void)b0; (void)b1;
}

extern "C" int solve_auction(int n, const double* cost, int* rowsol) {
    std::vector<double> price(n, 0.0);
