/*
 * Parallel Jacobi auction, 4 threads.
 * Each round every unassigned person computes a bid from a price snapshot;
 * the highest bid per object is applied. NEON/AVX not required; threads give 4x.
 */
#include <cstdint>
#include <cmath>
#include <cstring>
#include <algorithm>
#include <thread>
#include <vector>
#include <mutex>

static constexpr int T = 4;

struct Bid {
    int person;
    int obj;
    double price;
};

extern "C" int solve_auction(int n, const double* cost, int* rowsol) {
    std::vector<double> price(n, 0.0), price_snap(n);
    std::vector<int> owner(n, -1);
    std::vector<char> won(n);

    double maxc = 0;
    for (size_t k = 0, N = (size_t)n * n; k < N; ++k) if (cost[k] > maxc) maxc = cost[k];
    double eps = maxc / 4.0;
    const double eps_final = 1e-12;

    auto round_bids = [&](const std::vector<int>& uns, std::vector<Bid>& bids) {
        int m = (int)uns.size();
        bids.resize(m);
        auto worker = [&](int t) {
            int chunk = (m + T - 1) / T;
            int a = t * chunk, b = std::min(m, a + chunk);
            for (int tidx = a; tidx < b; ++tidx) {
                int i = uns[tidx];
                const double* row = cost + (size_t)i * n;
                const double* pr = price_snap.data();
                double best = 1e300, second = 1e300;
                int jbest = 0;
                for (int j = 0; j < n; ++j) {
                    double val = row[j] + pr[j];
                    if (val < best) { second = best; best = val; jbest = j; }
                    else if (val < second) second = val;
                }
                bids[tidx] = Bid{i, jbest, pr[jbest] + (second - best) + eps};
            }
        };
        std::thread th[T];
        for (int t = 0; t < T; ++t) th[t] = std::thread(worker, t);
        for (int t = 0; t < T; ++t) th[t].join();
    };

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::vector<int> uns(n), next;
        for (int i = 0; i < n; ++i) uns[i] = i;
        int guard = 0;
        bool failed = false;
        std::vector<Bid> bids;
        while (!uns.empty()) {
            if (++guard > n * 40) { failed = true; break; }
            price_snap = price;
            round_bids(uns, bids);
            // apply highest bid per object
            std::vector<int> best_who(n, -1);
            std::vector<double> best_bid(n, -1e300);
            for (auto& b : bids) {
                if (b.price > best_bid[b.obj]) {
                    best_bid[b.obj] = b.price;
                    best_who[b.obj] = b.person;
                }
            }
            std::fill(won.begin(), won.end(), 0);
            for (int j = 0; j < n; ++j) {
                int i = best_who[j];
                if (i < 0) continue;
                owner[j] = i;
                price[j] = best_bid[j];
                won[i] = 1;
            }
            next.clear();
            for (int i = 0; i < n; ++i) if (!won[i]) next.push_back(i);
            uns.swap(next);
        }
        if (eps <= eps_final) {
            if (failed) return -1;
            for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            return 0;
        }
        eps = std::max(eps * 0.25, eps_final);
        if (failed) std::fill(price.begin(), price.end(), 0.0);
    }
}
