#include <cstdint>
#include <cmath>
#include <algorithm>
#include <vector>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>

static constexpr int T = 4;

struct Pool {
    int n = 0;
    const double* cost = nullptr;
    const double* price = nullptr;
    const int* uns = nullptr;
    int nun = 0;
    double eps = 0;
    int* bid_obj;
    double* bid_price;
    std::atomic<int> remaining{0};
    std::mutex mu;
    std::condition_variable cv_start, cv_done;
    int epoch = 0;
    bool stop = false;
    std::vector<std::thread> threads;

    void worker(int tid) {
        int seen = 0;
        while (true) {
            std::unique_lock<std::mutex> lk(mu);
            cv_start.wait(lk, [&]{ return stop || epoch != seen; });
            if (stop) return;
            seen = epoch;
            lk.unlock();

            int chunk = (nun + T - 1) / T;
            int a = tid * chunk, b = std::min(nun, a + chunk);
            const double* pr = price;
            for (int t = a; t < b; ++t) {
                int i = uns[t];
                const double* row = cost + (size_t)i * n;
                double best = 1e300, second = 1e300;
                int jbest = 0;
                int j = 0;
                for (; j + 3 < n; j += 4) {
                    double v0 = row[j] + pr[j];
                    double v1 = row[j+1] + pr[j+1];
                    double v2 = row[j+2] + pr[j+2];
                    double v3 = row[j+3] + pr[j+3];
                    if (v0 < best) { second = best; best = v0; jbest = j; }
                    else if (v0 < second) second = v0;
                    if (v1 < best) { second = best; best = v1; jbest = j+1; }
                    else if (v1 < second) second = v1;
                    if (v2 < best) { second = best; best = v2; jbest = j+2; }
                    else if (v2 < second) second = v2;
                    if (v3 < best) { second = best; best = v3; jbest = j+3; }
                    else if (v3 < second) second = v3;
                }
                for (; j < n; ++j) {
                    double v = row[j] + pr[j];
                    if (v < best) { second = best; best = v; jbest = j; }
                    else if (v < second) second = v;
                }
                bid_obj[t] = jbest;
                bid_price[t] = pr[jbest] + (second - best) + eps;
            }
            if (remaining.fetch_sub(1) == 1) {
                std::lock_guard<std::mutex> lk2(mu);
                cv_done.notify_one();
            }
        }
    }

    void start(int nn) {
        n = nn;
        bid_obj = new int[nn];
        bid_price = new double[nn];
        for (int t = 0; t < T; ++t) threads.emplace_back(&Pool::worker, this, t);
    }
    ~Pool() {
        {
            std::lock_guard<std::mutex> lk(mu);
            stop = true;
            epoch++;
        }
        cv_start.notify_all();
        for (auto& th : threads) th.join();
        delete[] bid_obj;
        delete[] bid_price;
    }
    void run_round() {
        remaining.store(T);
        {
            std::lock_guard<std::mutex> lk(mu);
            epoch++;
        }
        cv_start.notify_all();
        std::unique_lock<std::mutex> lk(mu);
        cv_done.wait(lk, [&]{ return remaining.load() == 0; });
    }
};

extern "C" int solve_auction(int n, const double* cost, int* rowsol) {
    Pool pool;
    pool.start(n);
    pool.cost = cost;
    pool.n = n;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> uns(n), next;
    std::vector<char> won(n);

    double maxc = 0;
