#include <cstdint>
#include <cmath>
#include <algorithm>
#include <vector>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>

static constexpr int T = 4;

// Persistent pool: each round, split the CURRENT unassigned list across threads.
// Gauss-Seidel needs sequential price updates, so this is Jacobi-per-batch:
// we process the unassigned list in parallel (read-only prices), then apply
// bids in order (first bidder on an object wins this round, others retry).
// Applying in order and keeping only non-conflicting bids approximates GS
// and still converges; conflicts just retry.

struct Pool {
    int n = 0;
    const double* cost = nullptr;
    const double* price = nullptr;
    const int* uns = nullptr;
    int nun = 0;
    double eps = 0;
    int* bid_obj = nullptr;
    double* bid_delta = nullptr; // second-best - best
    std::atomic<int> remaining{0};
    std::mutex mu;
    std::condition_variable cv_start, cv_done;
    int epoch = 0;
    bool stop = false;
    std::vector<std::thread> threads;

    void worker(int tid) {
        int seen = 0;
        while (true) {
            std::unique_lock<std::mutex> lk(mu);
            cv_start.wait(lk, [&]{ return stop || epoch != seen; });
            if (stop) return;
            seen = epoch;
            int nun_local = nun;
            lk.unlock();

            int chunk = (nun_local + T - 1) / T;
            int a = tid * chunk, b = std::min(nun_local, a + chunk);
            const double* pr = price;
            for (int t = a; t < b; ++t) {
                int i = uns[t];
                const double* row = cost + (size_t)i * n;
                double best = 1e300, second = 1e300;
                int jbest = 0;
                for (int j = 0; j < n; ++j) {
                    double v = row[j] + pr[j];
                    if (v < best) { second = best; best = v; jbest = j; }
                    else if (v < second) second = v;
                }
                bid_obj[t] = jbest;
                bid_delta[t] = (second - best) + eps;
            }
            if (remaining.fetch_sub(1) == 1) {
                std::lock_guard<std::mutex> lk2(mu);
                cv_done.notify_one();
            }
        }
    }
    void start(int nn) {
        n = nn;
        bid_obj = new int[nn];
        bid_delta = new double[nn];
        for (int t = 0; t < T; ++t) threads.emplace_back(&Pool::worker, this, t);
    }
    ~Pool() {
        { std::lock_guard<std::mutex> lk(mu); stop = true; epoch++; }
        cv_start.notify_all();
        for (auto& th : threads) if (th.joinable()) th.join();
        delete[] bid_obj; delete[] bid_delta;
    }
    void run() {
        remaining.store(T);
        { std::lock_guard<std::mutex> lk(mu); epoch++; }
        cv_start.notify_all();
        std::unique_lock<std::mutex> lk(mu);
        cv_done.wait(lk, [&]{ return remaining.load() == 0; });
    }
};

extern "C" int solve_auction(int n, const double* cost, int* rowsol) {
    Pool pool;
    pool.start(n);
    pool.cost = cost;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> uns(n), next;
    std::vector<char> taken(n);

    double maxc = 0;
    for (size_t k = 0, N=(size_t)n*n; k < N; ++k) if (cost[k] > maxc) maxc = cost[k];
    double eps = maxc / 4.0;
    const double eps_final = 1e-12;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        for (int i = 0; i < n; ++i) uns[i] = i;
        int nun = n;
        int guard = 0;
        bool failed = false;
        while (nun > 0) {
            if (++guard > n * 40) { failed = true; break; }
            pool.price = price.data();
            pool.uns = uns.data();
            pool.nun = nun;
            pool.eps = eps;
            pool.run();
            // apply bids in order; if object already taken this round by a higher-priority
            // bidder, the person retries. Price updates are visible next round only
            // (Jacobi). To get GS-like speed, apply immediately and accept conflicts as retries.
            std::fill(taken.begin(), taken.end(), 0);
            next.clear();
            for (int t = 0; t < nun; ++t) {
                int i = uns[t];
                int j = pool.bid_obj[t];
                if (taken[j]) { next.push_back(i); continue; }
                taken[j] = 1;
                int prev = owner[j];
                if (prev >= 0) next.push_back(prev);
                owner[j] = i;
                price[j] += pool.bid_delta[t];
            }
            uns.swap(next);
            nun = (int)uns.size();
        }
        if (eps <= eps_final) {
            if (failed) return -1;
            for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            return 0;
        }
        double next_eps = std::max(eps * 0.2, eps_final);
        eps = next_eps;
        if (failed) std::fill(price.begin(), price.end(), 0.0);
    }
}
