/*
 * Gauss-Seidel auction, blocked + AVX2.
 * Process B unassigned persons at a time, scanning the cost matrix in
 * column-blocks so each block of the matrix is loaded once per group
 * and reused across the B persons (better cache behavior, ILP).
 */
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <vector>
#include <immintrin.h>

static constexpr int B = 8; // persons per block

extern "C" int solve_auction(int n, const double* cost, int* rowsol) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> uns(n), next;

    double maxc = 0;
    for (size_t k = 0, N=(size_t)n*n; k<N; ++k) if (cost[k] > maxc) maxc = cost[k];
    double eps = maxc / 4.0;
    const double eps_final = 1e-12;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        for (int i = 0; i < n; ++i) uns[i] = i;
        int nun = n;
        int guard = 0;
        bool failed = false;

        while (nun > 0) {
            if (++guard > n * 60) { failed = true; break; }
            next.clear();
            int t = 0;
            while (t < nun) {
                int b = std::min(B, nun - t);
                // if b < B, scalar path for the tail persons one by one (GS)
                if (b < B) {
                    for (int k = 0; k < b; ++k) {
                        int i = uns[t+k];
                        const double* row = cost + (size_t)i * n;
                        double best = 1e300, second = 1e300; int jbest = 0;
                        for (int j = 0; j < n; ++j) {
                            double v = row[j] + price[j];
                            if (v < best) { second = best; best = v; jbest = j; }
                            else if (v < second) second = v;
                        }
                        double np_ = price[jbest] + (second - best) + eps;
                        int prev = owner[jbest];
                        if (prev >= 0) next.push_back(prev);
                        owner[jbest] = i;
                        price[jbest] = np_;
                    }
                    break;
                }
                int persons[B];
                const double* rows[B];
                for (int k = 0; k < B; ++k) {
                    persons[k] = uns[t+k];
                    rows[k] = cost + (size_t)persons[k] * n;
                }
                double best[B], second[B];
                int jbest[B];
                for (int k = 0; k < B; ++k) { best[k] = 1e300; second[k] = 1e300; jbest[k] = 0; }

                // scan columns, update all B persons. Prices are the snapshot at block start
                // (Jacobi within the block) — then we apply bids GS-style in order.
                for (int j = 0; j < n; ++j) {
                    double pj = price[j];
                    for (int k = 0; k < B; ++k) {
                        double v = rows[k][j] + pj;
                        if (v < best[k]) { second[k] = best[k]; best[k] = v; jbest[k] = j; }
                        else if (v < second[k]) second[k] = v;
                    }
                }
                // apply in order; if two persons want the same object, the later one
                // recomputes against updated price (rare). For simplicity, apply and if
                // conflict, push loser to next.
                char claimed[/*n*/ 1];
                (void)claimed;
                // track objects claimed in this block
                int claimed_obj[B];
                int nclaimed = 0;
                for (int k = 0; k < B; ++k) {
                    int j = jbest[k];
                    // if a previous person in this block already bid on j, price changed;
                    // this person's best may be stale. Push to retry.
                    bool stale = false;
                    for (int c = 0; c < nclaimed; ++c) if (claimed_obj[c] == j) stale = true;
                    if (stale) { next.push_back(persons[k]); continue; }
                    double np_ = price[j] + (second[k] - best[k]) + eps;
                    int prev = owner[j];
                    if (prev >= 0) next.push_back(prev);
                    owner[j] = persons[k];
                    price[j] = np_;
                    claimed_obj[nclaimed++] = j;
                }
                t += B;
            }
            uns.swap(next);
            nun = (int)uns.size();
        }
        if (eps <= eps_final) {
            if (failed) return -1;
            for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            return 0;
        }
        eps = std::max(eps * 0.2, eps_final);
        if (failed) std::fill(price.begin(), price.end(), 0.0);
    }
}
