/*
 * K-nearest auction (Gauss-Seidel, integer benefits scaled by n).
 * Neighbor selection uses a simple heap-free partial selection (nth_element).
 * After auction, caller can verify. We also export a full-matrix repair:
 * if any reduced cost is negative outside the candidate set, we don't know
 * duals easily, so we just return the candidate assignment and a flag.
 */
#include <cstdint>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include <algorithm>
#include <vector>

extern "C" int solve_auction_k(int n, const double* cost_in, int K, int* rowsol) {
    if (K > n) K = n;
    const int64_t S = 1000000000LL;

    std::vector<int> neigh((size_t)n * K);
    std::vector<int64_t> brow((size_t)n * K);
    std::vector<int64_t> price(n, 0);
    std::vector<int> owner(n, -1);
    std::vector<int> unassigned(n), un2(n);
    std::vector<int64_t> tmp(n);
    std::vector<int> order(n);

    for (int i = 0; i < n; ++i) {
        const double* row = cost_in + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            tmp[j] = (int64_t)std::llrint(row[j] * (double)S);
            order[j] = j;
        }
        std::nth_element(order.begin(), order.begin() + K, order.end(),
                         [&](int a, int b){ return tmp[a] < tmp[b]; });
        for (int t = 0; t < K; ++t) {
            int j = order[t];
            neigh[(size_t)i * K + t] = j;
            brow[(size_t)i * K + t] = -tmp[j] * (int64_t)n;
        }
    }

    int64_t eps = S * (int64_t)n / 4;
    if (eps < 1) eps = 1;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int guard = 0;
        while (nun > 0 && guard < n * 40) {
            guard++;
            int nun2 = 0;
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                const int* nb = neigh.data() + (size_t)i * K;
                const int64_t* br = brow.data() + (size_t)i * K;
                int64_t best = -(int64_t)8e18, second = -(int64_t)8e18;
                int jbest = nb[0];
                for (int t2 = 0; t2 < K; ++t2) {
                    int j = nb[t2];
                    int64_t val = br[t2] - price[j];
                    if (val > best) { second = best; best = val; jbest = j; }
                    else if (val > second) second = val;
                }
                int64_t bid = price[jbest] + (best - second) + eps;
                int prev = owner[jbest];
                if (prev >= 0) un2[nun2++] = prev;
                owner[jbest] = i;
                price[jbest] = bid;
            }
            nun = nun2;
            unassigned.swap(un2);
        }
        if (eps == 1) {
            if (nun != 0) return -1;
            for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            return 0;
        }
        eps = std::max<int64_t>(eps / 5, 1);
    }
}
