#include <cstdint>
#include <cmath>
#include <algorithm>
#include <vector>
#include <immintrin.h>

// Branchless AVX2 scan: best and second-best of row[j] + price[j].
static inline void best_second(const double* row, const double* price, int n,
                               double& best, double& second, int& jbest) {
    __m256d bestv = _mm256_set1_pd(1e300);
    __m256d secondv = _mm256_set1_pd(1e300);
    __m256i besti = _mm256_set1_epi64x(-1);
    __m256i cur = _mm256_set_epi64x(3, 2, 1, 0);
    const __m256i step = _mm256_set1_epi64x(4);

    int j = 0;
    for (; j + 4 <= n; j += 4) {
        __m256d v = _mm256_add_pd(_mm256_loadu_pd(row + j), _mm256_loadu_pd(price + j));
        __m256d lt = _mm256_cmp_pd(v, bestv, _CMP_LT_OQ);
        // second = (v < best) ? old_best : ((v < second) ? v : second)
        __m256d sec = _mm256_blendv_pd(secondv, bestv, lt);
        __m256d lt2 = _mm256_cmp_pd(v, secondv, _CMP_LT_OQ);
        __m256d mid = _mm256_andnot_pd(lt, lt2);          // v >= best && v < second
        sec = _mm256_blendv_pd(sec, v, mid);
        secondv = sec;
        besti = _mm256_castpd_si256(_mm256_blendv_pd(
            _mm256_castsi256_pd(besti), _mm256_castsi256_pd(cur), lt));
        bestv = _mm256_min_pd(bestv, v);
        cur = _mm256_add_epi64(cur, step);
    }

    alignas(32) double bv[4], sv[4];
    alignas(32) int64_t bi[4];
    _mm256_store_pd(bv, bestv);
    _mm256_store_pd(sv, secondv);
    _mm256_store_si256(reinterpret_cast<__m256i*>(bi), besti);

    best = 1e300;
    second = 1e300;
    jbest = 0;
    for (int k = 0; k < 4; ++k) {
        if (bv[k] < best) {
            second = best;
            best = bv[k];
            jbest = (int)bi[k];
        } else if (bv[k] < second) {
            second = bv[k];
        }
        if (sv[k] < second) second = sv[k];
    }
    for (; j < n; ++j) {
        double v = row[j] + price[j];
        if (v < best) { second = best; best = v; jbest = j; }
        else if (v < second) second = v;
    }
}

extern "C" int solve_auction(int n, const double* cost, int* rowsol) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> unassigned(n), un2(n);

    double maxc = 0.0;
    for (size_t k = 0, N = (size_t)n * n; k < N; ++k)
        if (cost[k] > maxc) maxc = cost[k];

    double eps = maxc * 0.25;
    const double eps_final = 1e-12;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int guard = 0;
        bool failed = false;
        while (nun > 0) {
            if (++guard > n * 100) { failed = true; break; }
            int nun2 = 0;
            const double* pr = price.data();
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                double best, second;
                int jbest;
                best_second(cost + (size_t)i * n, pr, n, best, second, jbest);
                double new_price = pr[jbest] + (second - best) + eps;
                int prev = owner[jbest];
                if (prev >= 0) un2[nun2++] = prev;
                owner[jbest] = i;
                price[jbest] = new_price;
            }
            nun = nun2;
            unassigned.swap(un2);
        }
        if (eps <= eps_final) {
            if (failed) return -1;
            for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            return 0;
        }
        eps = std::max(eps * 0.2, eps_final);
        if (failed) std::fill(price.begin(), price.end(), 0.0);
    }
