    for (int k = 0; k < 4; ++k) {
        if (bv[k] < r.best) { r.second = r.best; r.best = bv[k]; r.jbest = (int)bi[k]; }
        else if (bv[k] < r.second) r.second = bv[k];
        if (sv[k] < r.second) r.second = sv[k];
    }
    for (; j < n; ++j) {
        double v = row[j] + price[j];
        if (v < r.best) { r.second = r.best; r.best = v; r.jbest = j; }
        else if (v < r.second) r.second = v;
    }
    return r;
