// Work-stealing style: atomic index over unassigned persons.
struct Ctx {
    const double* cost;
    const double* price;
    const int* uns;
    int n, nun;
    double eps;
    int* bid_obj;
    double* bid_raise;
    std::atomic<int> cursor{0};
    std::atomic<int> done{0};
};

static void worker(Ctx* ctx) {
    int n = ctx->n;
    while (true) {
        int t = ctx->cursor.fetch_add(1);
        if (t >= ctx->nun) break;
        int i = ctx->uns[t];
        Best b = scan(ctx->cost + (size_t)i * n, ctx->price, n);
        ctx->bid_obj[t] = b.jbest;
        ctx->bid_raise[t] = (b.second - b.best) + ctx->eps;
    }
    ctx->done.fetch_add(1);
}

extern "C" int solve_auction(int n, const double* cost, int* rowsol) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), uns(n), un2;
    std::vector<int> bid_obj(n);
    std::vector<double> bid_raise(n);
    std::vector<char> claimed(n);

    double maxc = 0;
    for (size_t k = 0, N=(size_t)n*n; k<N; ++k) if (cost[k] > maxc) maxc = cost[k];
    double eps = maxc * 0.25;
    const double eps_final = 1e-12;

    Ctx ctx;
    ctx.cost = cost;
    ctx.n = n;
    ctx.bid_obj = bid_obj.data();
    ctx.bid_raise = bid_raise.data();

    std::vector<std::thread> threads;
    // We spawn threads per round — expensive. Use persistent via a simple loop spawn only if nun is large.
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        for (int i = 0; i < n; ++i) uns[i] = i;
        int nun = n;
        int guard = 0;
        bool failed = false;
        while (nun > 0) {
            if (++guard > n * 50) { failed = true; break; }
            ctx.price = price.data();
            ctx.uns = uns.data();
            ctx.nun = nun;
            ctx.eps = eps;
            ctx.cursor.store(0);
            ctx.done.store(0);
            threads.clear();
            for (int t = 0; t < NT; ++t) threads.emplace_back(worker, &ctx);
            for (auto& th : threads) th.join();

            std::fill(claimed.begin(), claimed.end(), 0);
            un2.clear();
            for (int t = 0; t < nun; ++t) {
                int j = bid_obj[t];
                int i = uns[t];
                if (claimed[j]) { un2.push_back(i); continue; }
                claimed[j] = 1;
                int prev = owner[j];
                if (prev >= 0) un2.push_back(prev);
                owner[j] = i;
                price[j] += bid_raise[t];
            }
            uns.swap(un2);
            nun = (int)uns.size();
        }
        if (eps <= eps_final) {
            if (failed) return -1;
            for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            return 0;
        }
        eps = std::max(eps * 0.2, eps_final);
        if (failed) std::fill(price.begin(), price.end(), 0.0);
    }
}
