                int i = uns[t];
                Best b = scan(cost + (size_t)i * n, price, n);
                bid_obj[t] = b.jbest;
                bid_raise[t] = (b.second - b.best) + eps;
            }
            if (finished.fetch_add(1) == NT - 1) {
                std::lock_guard<std::mutex> lk2(mu);
                cv_done.notify_one();
            }
        }
    }
    void start() {
        for (int i = 0; i < NT; ++i) th.emplace_back(&Pool::worker, this);
    }
    ~Pool() {
        { std::lock_guard<std::mutex> lk(mu); stop = true; epoch++; }
        cv_go.notify_all();
        for (auto& t : th) if (t.joinable()) t.join();
    }
    void run() {
        cursor.store(0);
        finished.store(0);
        { std::lock_guard<std::mutex> lk(mu); epoch++; }
        cv_go.notify_all();
        std::unique_lock<std::mutex> lk(mu);
        cv_done.wait(lk, [&]{ return finished.load() == NT; });
    }
};

extern "C" int solve_auction(int n, const double* cost, int* rowsol) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), uns(n), un2;
    std::vector<int> bid_obj(n);
    std::vector<double> bid_raise(n);
    std::vector<char> claimed(n);

    Pool pool;
    pool.cost = cost;
    pool.n = n;
    pool.bid_obj = bid_obj.data();
    pool.bid_raise = bid_raise.data();
    pool.start();

    double maxc = 0;
    for (size_t k = 0, N=(size_t)n*n; k<N; ++k) if (cost[k] > maxc) maxc = cost[k];
    double eps = maxc * 0.25;
    const double eps_final = 1e-12;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        for (int i = 0; i < n; ++i) uns[i] = i;
        int nun = n;
        int guard = 0;
        bool failed = false;
        while (nun > 0) {
            if (++guard > n * 60) { failed = true; break; }
            pool.price = price.data();
            pool.uns = uns.data();
            pool.nun = nun;
            pool.eps = eps;
            pool.run();

            std::fill(claimed.begin(), claimed.end(), 0);
            un2.clear();
            for (int t = 0; t < nun; ++t) {
                int j = bid_obj[t];
                int i = uns[t];
                if (claimed[j]) { un2.push_back(i); continue; }
                claimed[j] = 1;
                int prev = owner[j];
                if (prev >= 0) un2.push_back(prev);
                owner[j] = i;
                price[j] += bid_raise[t];
            }
            uns.swap(un2);
            nun = (int)uns.size();
        }
        if (eps <= eps_final) {
            if (failed) return -1;
            for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            return 0;
        }
        eps = std::max(eps * 0.2, eps_final);
        if (failed) std::fill(price.begin(), price.end(), 0.0);
    }
}
